 // envToMap converts an env slice to a map for easy assertions.
 // For duplicate keys, the last value wins.
 func envToMap(env []string) map[string]string {
 	m := make(map[string]string, len(env))
 	for _, e := range env {
 		k, v, ok := strings.Cut(e, "=")
 		if ok {
 			m[k] = v
 		}
 	}
 	return m
 }

