 			"GIT_CONFIG_KEY_0=some.key",
 			"GIT_CONFIG_VALUE_0=some-value",
 			"GIT_CONFIG_KEY_1=other.key",
 			"REDACTED",
 		}, "new-token")

 		for _, e := range env {
